y without spikes.", "selected_profile_info": [null, "city_town", "religion", "name", "gender", "age", "describe_location", "describe_food", "disability", "occupation", "daily_routine", "hobbies", "activities", "health_conditions", "medication", "healthcare_resources", "healthcare_access", "healthcare_frequency", "culture", "t2d_status", "tobacco", "alcohol", "physical_activity", "diet_restrictions", "support_network", "Question", "generated_queries", "Category", "study_number", "health_goals", "output_format", "label", "story_arc", "type", "parent", "output_tone"]}
